import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';

const socket = io('http://localhost:3001');

function App() {
  const [gameState, setGameState] = useState(null);
  const [playerId, setPlayerId] = useState(null);
  const [isJoined, setIsJoined] = useState(false);
  const [logs, setLogs] = useState([]);
  const [playerName, setPlayerName] = useState('');
  const [selectedCharacter, setSelectedCharacter] = useState('');

  const characters = [
    'Prof. Plum',
    'Mrs. Peacock',
    'Mr. Green',
    'Miss Scarlet',
    'Col. Mustard',
    'Mrs. White',
  ];

  const addLog = (message) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs((prev) => [...prev, `[${timestamp}] ${message}`]);
  };

  useEffect(() => {
    // Socket event listeners for skeletal increment
    socket.on('gameJoined', (data) => {
      setPlayerId(data.playerId);
      setGameState(data.gameState);
      setIsJoined(true);
      addLog(`✓ Joined game successfully as ${selectedCharacter}`);
    });

    socket.on('gameStateUpdate', (data) => {
      setGameState(data);
      addLog('Game state updated');
    });

    socket.on('playerJoined', (data) => {
      addLog(`Player ${data.player.name} joined as ${data.player.character}`);
    });

    socket.on('gameStarted', (data) => {
      setGameState(data.gameState);
      addLog('🎮 Game started! Turn-based gameplay enabled');
    });

    socket.on('moveResult', (data) => {
      if (data.success) {
        addLog(
          `✓ Move successful - ${
            data.movedToRoom ? 'Entered room' : 'Moved to hallway'
          }`
        );
      }
    });

    socket.on('error', (data) => {
      addLog(`❌ Error: ${data.message}`);
    });

    return () => {
      socket.off('gameJoined');
      socket.off('gameStateUpdate');
      socket.off('playerJoined');
      socket.off('gameStarted');
      socket.off('moveResult');
      socket.off('error');
    };
  }, [selectedCharacter]);

  const joinGame = () => {
    if (playerName.trim() && selectedCharacter) {
      socket.emit('joinGame', {
        name: playerName.trim(),
        character: selectedCharacter,
      });
      addLog(`Attempting to join as ${selectedCharacter}...`);
    }
  };

  const markReady = () => {
    socket.emit('playerReady');
    addLog('Marked as ready - waiting for other players...');
  };

  const makeMove = (destination) => {
    socket.emit('makeMove', { destination });
    addLog(`Attempting to move to: ${destination}`);
  };

  const getAvailableMoves = () => {
    if (!gameState || !playerId || !gameState.players[playerId]) return [];

    const player = gameState.players[playerId];
    const location = player.location;
    const moves = [];

    if (location.includes('-')) {
      // In hallway - can move to connected rooms
      const hallway = gameState.board.hallways[location];
      if (hallway) {
        hallway.connects.forEach((roomId) => {
          const room = gameState.board.rooms[roomId];
          if (room) {
            moves.push({ id: roomId, name: room.name, type: 'room' });
          }
        });
      }
    } else {
      // In room - can move to connected hallways (if empty)
      Object.entries(gameState.board.hallways).forEach(
        ([hallwayId, hallway]) => {
          if (hallway.connects.includes(location) && !hallway.player) {
            moves.push({ id: hallwayId, name: hallway.name, type: 'hallway' });
          }
        }
      );
    }

    return moves;
  };

  if (!isJoined) {
    return (
      <div style={styles.container}>
        <div style={styles.header}>
          <h1>🕵️ CLUE-LESS</h1>
          <p>
            <strong>Architecture Demo:</strong> Client-Server Communication
          </p>
        </div>

        <div style={styles.joinForm}>
          <h2>Join Game (Basic Console Interface)</h2>

          <div style={styles.formGroup}>
            <label>Player Name:</label>
            <input
              type="text"
              value={playerName}
              onChange={(e) => setPlayerName(e.target.value)}
              placeholder="Enter your name"
              style={styles.input}
            />
          </div>

          <div style={styles.formGroup}>
            <label>Character:</label>
            <select
              value={selectedCharacter}
              onChange={(e) => setSelectedCharacter(e.target.value)}
              style={styles.input}
            >
              <option value="">Select character</option>
              {characters.map((char) => (
                <option key={char} value={char}>
                  {char}
                </option>
              ))}
            </select>
          </div>

          <button onClick={joinGame} style={styles.button}>
            Join Game
          </button>
        </div>

        <div style={styles.logs}>
          <h3>Connection Logs:</h3>
          <div style={styles.logContainer}>
            {logs.map((log, index) => (
              <div key={index} style={styles.logEntry}>
                {log}
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  const currentPlayer = gameState?.players[playerId];
  const isMyTurn = gameState?.currentPlayer === playerId;
  const availableMoves = getAvailableMoves();

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1>🕵️ CLUE-LESS</h1>
        <p>
          <strong>Status:</strong> {gameState?.gamePhase} |{' '}
          <strong>Players:</strong>{' '}
          {Object.keys(gameState?.players || {}).length}
        </p>
      </div>

      {/* Architecture Display */}
      <div style={styles.section}>
        <h2>🏗️ Architecture Components</h2>
        <div style={styles.grid}>
          <div style={styles.card}>
            <h3>Client-Server</h3>
            <p>✓ Socket.IO Communication</p>
            <p>✓ Real-time State Sync</p>
          </div>
          <div style={styles.card}>
            <h3>Data Structures</h3>
            <p>✓ 3×3 Room Grid</p>
            <p>✓ Hallway Nodes</p>
            <p>✓ Player Objects</p>
          </div>
          <div style={styles.card}>
            <h3>Game Flow</h3>
            <p>✓ Turn Management</p>
            <p>✓ State Updates</p>
            <p>✓ Message Passing</p>
          </div>
        </div>
      </div>

      {/* Player Status */}
      <div style={styles.section}>
        <h2>👥 Player Status</h2>
        <p>
          <strong>You:</strong> {currentPlayer?.name} (
          {currentPlayer?.character})
        </p>
        <p>
          <strong>Location:</strong> {currentPlayer?.location}
        </p>
        {isMyTurn && <p style={styles.highlight}>🎯 YOUR TURN</p>}
      </div>

      {/* Game Controls */}
      <div style={styles.section}>
        <h2>🎮 Game Controls</h2>

        {!gameState?.gameStarted && (
          <div>
            <p>
              Players ready:{' '}
              {
                Object.values(gameState?.players || {}).filter((p) => p.isReady)
                  .length
              }
              /{Object.keys(gameState?.players || {}).length}
            </p>
            {!currentPlayer?.isReady && (
              <button onClick={markReady} style={styles.button}>
                Mark Ready
              </button>
            )}
          </div>
        )}

        {gameState?.gameStarted && isMyTurn && (
          <div>
            <h3>Available Moves:</h3>
            {availableMoves.length > 0 ? (
              <div style={styles.moveButtons}>
                {availableMoves.map((move) => (
                  <button
                    key={move.id}
                    onClick={() => makeMove(move.id)}
                    style={styles.moveButton}
                  >
                    Move to {move.name} ({move.type})
                  </button>
                ))}
              </div>
            ) : (
              <p>No moves available</p>
            )}
          </div>
        )}

        {gameState?.gameStarted && !isMyTurn && (
          <p>
            Waiting for {gameState?.players[gameState?.currentPlayer]?.name}'s
            turn...
          </p>
        )}
      </div>

      {/* Board Visualization */}
      <div style={styles.section}>
        <h2>🗺️ Board State (Console View)</h2>
        <div style={styles.boardInfo}>
          <div style={styles.column}>
            <h4>Rooms with Players:</h4>
            {Object.entries(gameState?.board?.rooms || {}).map(
              ([roomId, room]) =>
                room.players.length > 0 && (
                  <div key={roomId} style={styles.locationEntry}>
                    {room.name}: [{room.players.join(', ')}]
                  </div>
                )
            )}
          </div>

          <div style={styles.column}>
            <h4>Occupied Hallways:</h4>
            {Object.entries(gameState?.board?.hallways || {}).map(
              ([hallwayId, hallway]) =>
                hallway.player && (
                  <div key={hallwayId} style={styles.locationEntry}>
                    {hallway.name}: {hallway.player}
                  </div>
                )
            )}
          </div>
        </div>
      </div>

      {/* Communication Logs */}
      <div style={styles.section}>
        <h2>📡 Communication Log</h2>
        <div style={styles.logContainer}>
          {logs.slice(-10).map((log, index) => (
            <div key={index} style={styles.logEntry}>
              {log}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: {
    maxWidth: '1000px',
    margin: '0 auto',
    padding: '20px',
    backgroundColor: '#1a1a1a',
    color: '#ffffff',
    fontFamily: 'monospace',
    minHeight: '100vh',
  },
  header: {
    textAlign: 'center',
    marginBottom: '30px',
    padding: '20px',
    backgroundColor: '#2a2a2a',
    borderRadius: '8px',
  },
  section: {
    marginBottom: '30px',
    padding: '20px',
    backgroundColor: '#2a2a2a',
    borderRadius: '8px',
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
    gap: '15px',
  },
  card: {
    backgroundColor: '#3a3a3a',
    padding: '15px',
    borderRadius: '8px',
  },
  joinForm: {
    backgroundColor: '#2a2a2a',
    padding: '30px',
    borderRadius: '8px',
    marginBottom: '20px',
  },
  formGroup: {
    marginBottom: '15px',
  },
  input: {
    width: '100%',
    padding: '10px',
    backgroundColor: '#3a3a3a',
    border: '1px solid #555',
    borderRadius: '4px',
    color: '#ffffff',
    marginTop: '5px',
  },
  button: {
    backgroundColor: '#4CAF50',
    color: 'white',
    padding: '12px 24px',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    margin: '5px',
  },
  moveButtons: {
    display: 'flex',
    flexDirection: 'column',
    gap: '8px',
  },
  moveButton: {
    backgroundColor: '#2196F3',
    color: 'white',
    padding: '10px 15px',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    textAlign: 'left',
  },
  highlight: {
    color: '#ff6b6b',
    fontWeight: 'bold',
    fontSize: '18px',
  },
  boardInfo: {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr',
    gap: '20px',
  },
  column: {
    backgroundColor: '#3a3a3a',
    padding: '15px',
    borderRadius: '8px',
  },
  locationEntry: {
    padding: '5px',
    backgroundColor: '#4a4a4a',
    margin: '5px 0',
    borderRadius: '4px',
    fontSize: '14px',
  },
  logContainer: {
    backgroundColor: '#1a1a1a',
    padding: '15px',
    borderRadius: '8px',
    maxHeight: '200px',
    overflowY: 'auto',
    border: '1px solid #555',
  },
  logEntry: {
    padding: '3px 0',
    fontSize: '12px',
    color: '#cccccc',
    borderBottom: '1px solid #333',
  },
};

export default App;
